<canvas id="film" width="960" height="540"></canvas>
<footer>
  <button id="play">Play · 30 seconds</button>
  <small>WALK ANYWAY · Illustrated animatic · Sound on</small>
</footer>
<script>
const canvas = document.querySelector("#film");
const c = canvas.getContext("2d");
const button = document.querySelector("#play");
const W = 960, H = 540;
let running = false, started = 0, spoken = false;
let audio, rainGain, rainSource;

function path(points, color, width = 1) {
  c.beginPath();
  points.forEach(([x,y],i) => i ? c.lineTo(x,y) : c.moveTo(x,y));
  c.strokeStyle = color; c.lineWidth = width; c.stroke();
}
function ellipse(x,y,rx,ry,color) {
  c.fillStyle = color; c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2); c.fill();
}
function rect(x,y,w,h,color) {
  c.fillStyle=color; c.fillRect(x,y,w,h);
}
function title() {
  rect(0,0,W,H,"#000");
  c.fillStyle="#fff"; c.textAlign="center"; c.textBaseline="middle";
  c.font="400 48px Arial, sans-serif";
  c.fillText("WALK ANYWAY",W/2,H/2);
}
function background(t, close=false) {
  const sky=c.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,"#0a1422");
  sky.addColorStop(1,"#273445");
  c.fillStyle=sky; c.fillRect(0,0,W,H);

  // Buildings and muted, reflected city light.
  for(let i=0;i<12;i++){
    const x=i*88-30, top=50+(i*67)%150;
    rect(x,top,75,390-top,"#111c2a");
    for(let j=0;j<4;j++)
      rect(x+15,top+25+j*44,8,12,
        (i+j)%3 ? "#293341" : "#78664d");
  }
  rect(0,390,W,150,"#182433");
  for(let i=0;i<28;i++){
    const x=(i*137)%W;
    rect(x,407+(i*29)%120,16+(i%4)*13,2,
      i%3 ? "#34485c" : "#77664d");
  }

  // One bus shelter, unchanged across the exterior shots.
  if(!close){
    rect(160,178,360,12,"#101820");
    rect(174,190,7,206,"#65717a");
    rect(494,190,7,206,"#65717a");
    rect(184,195,305,156,"#293744");
    rect(191,202,289,142,"#354451");
    rect(195,204,280,5,"#c3ac79");
    rect(202,349,247,9,"#514d43");
    rect(215,357,6,39,"#202b34");
    rect(430,357,6,39,"#202b34");
    rect(535,225,5,171,"#65717a");
    rect(518,215,39,35,"#9bafa9");
    // Bus icon without extra words.
    rect(527,222,21,17,"#243c46");
    rect(530,225,15,7,"#9bafa9");
    ellipse(532,240,2,2,"#243c46");
    ellipse(543,240,2,2,"#243c46");
  }
}
function umbrella(x,y,s=1){
  c.save(); c.translate(x,y); c.scale(s,s);
  path([[0,0],[0,153],[8,161],[15,154]],"#9ba0a2",3);
  c.fillStyle="#101217"; c.beginPath();
  c.moveTo(-108,9);
  c.quadraticCurveTo(-87,-61,0,-69);
  c.quadraticCurveTo(87,-61,108,9);
  c.quadraticCurveTo(81,-8,54,9);
  c.quadraticCurveTo(27,-8,0,9);
  c.quadraticCurveTo(-27,-8,-54,9);
  c.quadraticCurveTo(-81,-8,-108,9);
  c.fill();
  path([[-108,9],[-70,-32],[0,-69],[70,-32],[108,9]],
    "#454952",1.3);
  path([[0,-69],[0,9]],"#454952",1);
  path([[0,-77],[0,-69]],"#93979b",2);
  c.restore();
}
function person(x,y,s,kind,opts={}){
  const {rear=false,walk=0,smile=false,talk=false}=opts;
  c.save(); c.translate(x,y); c.scale(s,s);
  const woman=kind==="woman";
  const skin=woman?"#d9ad99":"#c5967f";
  const sway=walk ? Math.sin(walk)*7 : 0;
  c.translate(0,walk ? Math.abs(Math.sin(walk))*-2 : 0);

  // Boots and legs remain visibly different for the two characters.
  const boot=woman?"#e9bd3d":"#171b1d";
  path([[-12,110],[-13+sway,157]],
    woman?"#29313c":"#26312f",13);
  path([[12,110],[13-sway,157]],
    woman?"#29313c":"#26312f",13);
  rect(-22+sway,147,17,woman?28:19,boot);
  rect(5-sway,147,17,woman?28:19,boot);
  rect(-24+sway,168,24,7,boot);
  rect(3-sway,168,24,7,boot);

  // Coats.
  c.fillStyle=woman?"#b82e37":"#3d594c";
  c.beginPath();
  c.moveTo(-22,18); c.quadraticCurveTo(-35,45,-37,116);
  c.lineTo(36,116); c.quadraticCurveTo(33,48,22,18);
  c.closePath(); c.fill();
  path([[-23,33],[-39,86]],woman?"#a82530":"#344b40",13);
  path([[23,33],[37,85]],woman?"#a82530":"#344b40",13);
  ellipse(-39,90,6,8,skin);
  ellipse(37,89,6,8,skin);
  path([[0,28],[0,113]],woman?"#e45f60":"#647d6d",1);
  if(!rear) for(let i=0;i<4;i++)
    ellipse(6,48+i*16,1.5,1.5,"#a49b85");
  rect(-7,9,14,16,skin);

  // The woman's fixed silver bob; the man's fixed grey hair and beard.
  if(woman){
    ellipse(0,-7,25,29,"#c7cdd4");
    rect(-25,-9,50,34,"#c7cdd4");
  } else {
    ellipse(0,-9,24,25,"#929796");
  }
  if(!rear){
    ellipse(0,-5,19,25,skin);
    if(woman){
      c.fillStyle="#d6dbe0"; c.beginPath();
      c.moveTo(-24,0); c.lineTo(-23,-19);
      c.quadraticCurveTo(0,-43,24,-15);
      c.lineTo(23,0); c.lineTo(8,-14);
      c.lineTo(-9,-10); c.closePath(); c.fill();
    } else {
      c.fillStyle="#aeb2af"; c.beginPath();
      c.moveTo(-20,0); c.lineTo(-16,23);
      c.quadraticCurveTo(0,38,17,21);
      c.lineTo(20,0); c.lineTo(10,10);
      c.lineTo(-10,10); c.closePath(); c.fill();
    }
    ellipse(-7,-3,1.6,1.6,"#24262a");
    ellipse(7,-3,1.6,1.6,"#24262a");
    path([[0,0],[-2,6],[2,6]],"#a17564",1);
    if(talk){
      ellipse(0,14,4,2.5+Math.sin(performance.now()/85)*1.5,"#573b36");
    } else {
      c.beginPath(); c.moveTo(-6,12);
      c.quadraticCurveTo(0,smile?20:14,6,12);
      c.strokeStyle="#774c48"; c.lineWidth=1.5; c.stroke();
    }
  } else if(!woman){
    ellipse(0,6,18,19,"#929796");
  }
  c.restore();
}
function rain(t){
  c.lineWidth=1; c.strokeStyle="rgba(176,204,225,.35)";
  c.beginPath();
  for(let i=0;i<190;i++){
    const x=((i*79.73-t*80)%1020+1020)%1020-30;
    const y=(i*53.19+t*(390+i%7*23))%570-20;
    c.moveTo(x,y); c.lineTo(x-5,y+14);
  }
  c.stroke();
}
function frame(t){
  if(t<2 || t>=28){title();return}
  if(t<8){
    background(t);
    person(350,252,0.85,"woman");
  } else if(t<15){
    background(t);
    const p=Math.min(1,(t-8)/5);
    const x=790+(419-790)*p;
    person(350,252,0.85,"woman");
    person(x,265,0.79,"man",{walk:p<1?t*8:0});
    umbrella(x-22,208,0.9);
  } else if(t<21){
    background(t,true);
    // A cut to a close two-shot; same reusable character drawings.
    person(370,282,2.12,"woman",{smile:t>18});
    person(556,302,1.94,"man",{talk:t>16 && t<18});
    umbrella(490,143,2.25);
  } else {
    background(t);
    const p=(t-21)/7, s=0.88-p*0.36;
    const y=262-p*32, x=405+p*115;
    person(x-34,y,s,"woman",{rear:true,walk:t*7});
    person(x+31,y+12,s*0.93,"man",{rear:true,walk:t*7+1});
    umbrella(x,y-47*s,s);
  }
  rain(t);
  // Restrained edge shading.
  const vignette=c.createRadialGradient(480,270,140,480,270,570);
  vignette.addColorStop(0,"transparent");
  vignette.addColorStop(1,"rgba(0,0,0,.48)");
  c.fillStyle=vignette; c.fillRect(0,0,W,H);
}
function speak(){
  if(!("speechSynthesis" in window)) return;
  const u=new SpeechSynthesisUtterance("You came back.");
  u.lang="en-GB"; u.rate=0.8; u.pitch=0.78; u.volume=0.95;
  const voices=speechSynthesis.getVoices();
  u.voice=voices.find(v=>/en/i.test(v.lang) &&
    /David|Daniel|George|James|Male/i.test(v.name))
    ||voices.find(v=>/^en/.test(v.lang))||null;
  speechSynthesis.speak(u);
}
async function startRain(){
  const AC=window.AudioContext||window.webkitAudioContext;
  if(!AC) return;
  audio=audio||new AC();
  await audio.resume();
  const buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate);
  const data=buffer.getChannelData(0);
  for(let i=0;i<data.length;i++) data[i]=Math.random()*2-1;
  rainSource=audio.createBufferSource();
  rainSource.buffer=buffer; rainSource.loop=true;
  const filter=audio.createBiquadFilter();
  filter.type="lowpass"; filter.frequency.value=2300;
  rainGain=audio.createGain(); rainGain.gain.value=0.065;
  rainSource.connect(filter).connect(rainGain).connect(audio.destination);
  rainSource.start();
}
function stop(){
  running=false;
  if(rainSource){try{rainSource.stop()}catch(e){} rainSource=null}
  if("speechSynthesis" in window) speechSynthesis.cancel();
  title(); button.textContent="Replay · 30 seconds";
}
function tick(now){
  if(!running)return;
  const t=(now-started)/1000;
  if(t>=30){stop();return}
  if(t>=16 && !spoken){spoken=true;speak()}
  frame(t); requestAnimationFrame(tick);
}
button.onclick=async()=>{
  if(running){stop();return}
  spoken=false;
  if("speechSynthesis" in window) speechSynthesis.cancel();
  try{await startRain()}catch(e){console.warn("Audio unavailable",e)}
  running=true; started=performance.now();
  button.textContent="Stop";
  requestAnimationFrame(tick);
};
if("speechSynthesis" in window) speechSynthesis.getVoices();
title();
</script>
